nextflow_process {

    name "Test Process ASSEMBLYSCAN"
    script "../main.nf"
    process "ASSEMBLYSCAN"
    tag "modules"
    tag "modules_nfcore"
    tag "assemblyscan"

      test("genome.fasta - json") {

        when {
            config './json.config'
            process {
                """
                input[0] =  [ [ id:'test', single_end:false ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }

    test("genome.fasta") {

        when {
            process {
                """
                input[0] =  [ [ id:'test', single_end:false ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }

    test("genome.fasta - stub") {

        options "-stub"
        when {
            process {
                """
                input[0] =  [ [ id:'test', single_end:false ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }
}

